"""Complete 20 original anxiety, trauma and OCD questions."""
from create_psych_anxiety_diagnosis import rows,q,GA,OC,PT,AS,ref
from qbank_authoring import finalize

q('For established panic disorder, which long-term treatment approach is evidence-based?', 'Panic-focused CBT and/or an appropriate SSRI selected through shared decision-making',[
 ('Long-term benzodiazepine monotherapy as the preferred default','Dependence and poorer long-term outcomes make this an unsuitable routine strategy.'),('Repeated emergency reassurance alone without a structured plan','This does not adequately address maintaining fear and avoidance.'),('A beta blocker alone as a complete treatment of the panic-disorder syndrome','It may affect some autonomic symptoms but is not the standard core treatment.')],
 'Treat anticipatory fear and avoidance as well as attacks','**CBT can address catastrophic interpretation and use exposure to feared sensations and situations.**',['SSRIs can reduce panic burden but benefit is not immediate.','Start and titrate with attention to early activation and tolerability.'],'**Agree functional goals and monitor response.**',['Explain expected time course and withdrawal considerations.','Reassess the diagnosis if new medical red flags appear.'],[['CBT','Fear interpretation/exposure'],['SSRI','Evidence-based drug option'],['Long-term benzodiazepine','Not routine preferred care']],[GA])

q('A patient beginning an SSRI for panic disorder reports increased jitteriness in the first few days but has no mania or severe adverse reaction. Which explanation and plan are appropriate?', 'Early activation can occur before therapeutic benefit; review tolerability and use careful titration with follow-up',[
 ('This proves permanent drug failure after only a few days','A very early period is insufficient to judge the full therapeutic effect.'),('It establishes bipolar mania from jitteriness alone','Mania requires a broader sustained syndrome.'),('Abruptly increase to the maximum dose to overcome all activation','Aggressive escalation can worsen tolerability.')],
 'Prepare patients for the early treatment phase','**Initial anxiety can precede the later antipanic effect.**',['Assess severity, safety and alternative explanations.','A low starting dose and gradual increase can improve tolerability.'],'**Individualize the plan rather than dismissing symptoms.**',['Review for significant agitation, suicidal thinking or a polarity switch if symptoms suggest them.','Discuss when and how to obtain prompt review.'],[['Early phase','Possible activation'],['Benefit','Usually delayed'],['Plan','Careful dose review and monitoring']],[GA],style='clinical_scenario')

q('Why are benzodiazepines generally unsuitable as the routine long-term treatment of GAD or panic disorder?', 'Tolerance, dependence, withdrawal and cognitive/fall risks complicate long-term use',[
 ('They have no acute anxiolytic effect','They can reduce acute symptoms; that does not establish long-term net benefit.'),('They are all antidepressants with delayed onset','Their mechanism and onset differ from SSRIs/SNRIs.'),('Abrupt discontinuation is safe once anxiety improves','Withdrawal can be severe, including seizures in susceptible patients.')],
 'Short-term symptom relief is not the whole outcome','**The risk-benefit balance changes with prolonged exposure.**',['Selected brief crisis use is distinct from routine maintenance.','Age, respiratory disease, alcohol/opioids and falls alter risk.'],'**Prefer evidence-based longer-term strategies and taper established use safely.**',['Do not suddenly stop a dependent patient’s medication.','Use a coordinated gradual reduction plan when appropriate.'],[['Short term','Can relieve anxiety'],['Long term','Dependence/cognitive and safety burdens'],['Stopping','Gradual individualized plan']],[GA])

q('A patient with impairing GAD prefers medication but cannot tolerate adequate trials of SSRIs or SNRIs. Under NICE guidance, which alternative may be considered?', 'Pregabalin after individual risk assessment',[
 ('Clozapine as the routine next-line anxiety drug','Its risk burden and indication do not fit this routine GAD step.'),('Lamotrigine as an established first-choice GAD monotherapy','It is not the corresponding evidence-based option.'),('A stimulant to reduce the duration of worry','Stimulants are not routine GAD treatment and can worsen anxiety.')],
 'Alternative treatment still needs safety assessment','**Pregabalin is a guideline option when SSRIs/SNRIs are not tolerated.**',['Assess misuse/dependence, sedation, renal dosing and pregnancy-related considerations.','Psychological treatment remains an important option.'],'**Use shared review of benefit and harm.**',['Avoid combining sedating drugs without assessing respiratory and fall risks.','Plan eventual discontinuation rather than abrupt withdrawal.'],[['Context','SSRI/SNRI intolerance'],['Option','Pregabalin'],['Safety','Renal, sedation and dependence review']],[GA],style='clinical_scenario')

q('What is the central behavioral component of CBT for OCD?', 'Exposure to feared cues while preventing the usual compulsive response',[
 ('Repeated reassurance until every doubt is eliminated','Reassurance can become part of the maintaining compulsion cycle.'),('Encouraging the ritual whenever anxiety rises','This reinforces short-term relief and the cycle.'),('Avoiding every trigger indefinitely','Avoidance generally maintains the disorder.')],
 'Exposure and response prevention changes the maintaining cycle','**ERP helps the patient experience uncertainty and distress without neutralizing rituals.**',['It is collaborative and graded rather than coercive.','Mental rituals and family accommodation may also need attention.'],'**Set meaningful goals and practice between sessions.**',['Adapt intensity to severity and engagement.','Combine with medication when indicated by impairment and response.'],[['Exposure','Approach feared cues'],['Response prevention','Reduce ritual/neutralization'],['Learning','Tolerate uncertainty without compulsion']],[OC])

q('An adult with OCD has taken a tolerated SSRI at an appropriate dose for 2 weeks without meaningful improvement. Which conclusion is most appropriate?', 'It is too early to declare an adequate OCD medication trial unsuccessful',[
 ('Two weeks without response proves treatment resistance','OCD response often takes substantially longer.'),('All SSRI treatment should be stopped immediately because only benzodiazepines work','SSRIs are established OCD treatments.'),('The lack of early benefit proves the original obsessions were delusions','Treatment timing does not establish a different diagnosis.')],
 'OCD treatment often needs patience and dose optimization','**An adequate trial commonly extends toward twelve weeks with appropriate titration.**',['Tolerability and adherence must be reviewed.','ERP can be offered alongside medication.'],'**Monitor improvement in time cost and function as well as distress.**',['Review early adverse effects and safety.','Do not prolong an ineffective regimen indefinitely without a defined reassessment.'],[['2 weeks','Usually too early'],['Adequate trial','Dose, duration and adherence'],['Combined care','ERP when appropriate']],[OC],style='clinical_scenario')

q('After inadequate response to appropriate SSRI treatment for OCD, clomipramine is considered. Which safety issue is particularly relevant?', 'Anticholinergic effects, conduction/cardiac risk and toxicity in overdose',[
 ('A guarantee of no interactions because it is a tricyclic','Tricyclics have important interactions and adverse effects.'),('No need to review ECG or cardiovascular history in any patient','Cardiac assessment is important where indicated.'),('Immediate unrestricted combination with another serotonergic drug','Serotonergic and pharmacokinetic interactions require careful planning.')],
 'An effective alternative can have a different safety burden','**Clomipramine is serotonergic but also has important tricyclic effects.**',['Review cardiac disease, other drugs and overdose risk.','Specialist sequencing and monitoring improve safety.'],'**Use an individualized trial rather than automatic polypharmacy.**',['Assess bowel, urinary and ocular anticholinergic risks.','Continue evidence-based psychological treatment as appropriate.'],[['Potential benefit','OCD symptom reduction'],['Risks','Anticholinergic/cardiac/overdose'],['Plan','Careful selection and monitoring']],[OC])

q('An adult with established PTSD is ready to engage in treatment. Which psychological approach is recommended?', 'A validated trauma-focused intervention such as trauma-focused CBT or EMDR as appropriate',[
 ('Mandatory unstructured retelling immediately after every exposure','This is not equivalent to a structured evidence-based therapy.'),('Long-term avoidance of all trauma reminders as the treatment goal','Avoidance can maintain PTSD.'),('Medication alone must always precede any psychological treatment','Trauma-focused therapy can be a primary treatment option.')],
 'Trauma-focused treatment is structured and collaborative','**Therapy addresses trauma memories, meanings and avoidance within an evidence-based framework.**',['Preference, readiness, dissociation and practical circumstances affect delivery.','EMDR and specific CBT approaches have defined protocols.'],'**Provide safety and practical support alongside treatment.**',['Review comorbid depression and substance use.','Adapt treatment without assuming all distress requires immediate forced exposure.'],[['Approach','Trauma-focused'],['Choice','Collaborative'],['Support','Safety and comorbidity care']],[PT],style='clinical_scenario')

q('Should a single psychologically focused debriefing session be routinely imposed on everyone immediately after trauma to prevent PTSD?', 'No; routine compulsory debriefing is not recommended',[
 ('Yes; it reliably prevents PTSD in all exposed people','Evidence does not support that claim and there may be harm.'),('Yes; refusal to recount the event proves a psychiatric disorder','People differ in immediate coping and readiness.'),('No; therefore no practical or emotional support should be offered','Appropriate supportive care is distinct from compulsory debriefing.')],
 'Support does not require compelled immediate processing','**Early practical help, safety and information can be provided without forcing detailed retelling.**',['Many people recover without a disorder.','Clinically important acute symptoms still warrant assessment and indicated treatment.'],'**Monitor needs and offer evidence-based care when appropriate.**',['Respect autonomy and cultural context.','Arrange review if persistent or worsening symptoms impair function.'],[['Compulsory debriefing','Not routine prevention'],['Support','Still appropriate'],['Persistent symptoms','Assess and treat']],[PT])

q('A patient with panic-like episodes now develops exertional syncope, persistent chest pain and a new abnormal ECG. Which response is appropriate?', 'Urgently reassess medical causes rather than attributing the new presentation to the existing anxiety diagnosis',[
 ('Assume panic disorder explains every future cardiopulmonary symptom','A previous psychiatric diagnosis does not exclude new disease.'),('Increase anxiolytics before evaluating the red flags','This may delay treatment of a serious cause.'),('Exclude cardiac disease because previous investigations were normal','New symptoms and findings change the assessment.')],
 'Avoid diagnostic overshadowing','**Anxiety and medical disease can coexist.**',['The symptom pattern and objective findings determine the workup.','Reassurance should follow an appropriate current assessment.'],'**Treat immediate danger and then coordinate the continuing anxiety plan.**',['Consider arrhythmia, ischemia and other relevant causes.','Communicate the reasons for reassessment without dismissing prior anxiety symptoms.'],[['Prior diagnosis','Does not exclude new disease'],['Red flags','Syncope/chest pain/ECG change'],['Action','Urgent medical review']],[GA],style='clinical_scenario')

if __name__=='__main__':finalize('Psychiatry',3,'Anxiety, Trauma and Obsessive-compulsive Disorders','psych-anxiety',rows,20)
